-- Import of PF 2025 official exam items for career "Delegado de Polícia
-- Federal" (Edital nº 1 – PF – Policial, de 20 de maio de 2025, retificado
-- pelo Edital nº 9, de 16/09/2025; concurso público para os cargos de
-- Delegado de Polícia Federal, Perito Criminal Federal, Escrivão de Polícia
-- Federal, Agente de Polícia Federal e Papiloscopista Policial Federal;
-- banca CEBRASPE; prova aplicada em 27/07/2025). This is a NEW edition
-- (exam_year=2025), distinct from the existing 2021 Delegado edition
-- imported by 20260929240000_pf_2021_delegado_import.sql. contest_name
-- stays 'Polícia Federal'; career_name stays 'Delegado de Polícia Federal';
-- exam_year distinguishes the two editions.
--
-- Source material read verbatim from Google Drive:
--   - Prova objetiva (itens 1-120, conhecimentos específicos): 106_PF_001_01.pdf
--     (fileId 1wspbjh9e8Q2m1I9IpKkbvqCftgrbgW_q). Footer reads
--     "CEBRASPE – PF – Edital: 2025". Cargo 1: Delegado de Polícia Federal.
--   - Gabarito objetivo definitivo: 106_PF_25_GabaritosDefinitivos (fileId
--     1wrV8FqTy-BxpK2daJLrEQ44uC9eNe-hu), explicitly labeled
--     "CARGO 1: DELEGADO DE POLÍCIA FEDERAL", 106_PF_001_01. "( X )" marks
--     an annulled item.
-- Not used for these objective items (context only, not transcribed):
-- prova discursiva (fileId 1BCe3al4wy0cZI3oNbb1JKeAwRhEnxJKr) and padrão de
-- resposta discursiva (fileId 19YlpnHwE8HjyKw0mi4LCzXUMa7umcDoY).

-- Content sources for this cargo's booklet and gabarito.
insert into public.content_sources (source_type,title,issuer,url,status,notes) values
('outro','Prova objetiva PF - Delegado - 2025','Polícia Federal / CEBRASPE','https://drive.google.com/file/d/1wspbjh9e8Q2m1I9IpKkbvqCftgrbgW_q/view','vigente','Caderno oficial 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal), Edital nº 1 – PF – Policial, de 20/05/2025, prova aplicada em 27/07/2025 (Google Drive fileId 1wspbjh9e8Q2m1I9IpKkbvqCftgrbgW_q, texto lido verbatim nesta sessão).'),
('outro','Gabarito definitivo PF - Delegado - 2025','Polícia Federal / CEBRASPE','https://drive.google.com/file/d/1wrV8FqTy-BxpK2daJLrEQ44uC9eNe-hu/view','vigente','Gabarito oficial definitivo 106_PF_001_01, explicitamente rotulado CARGO 1: DELEGADO DE POLÍCIA FEDERAL (Google Drive fileId 1wrV8FqTy-BxpK2daJLrEQ44uC9eNe-hu); X identifica item anulado.')
on conflict (url) do update set checked_at=now(),status=excluded.status,notes=excluded.notes;

-- New syllabus edition for this exam year (distinct from the existing 2021
-- Delegado edition row).
insert into public.syllabus_editions (contest_name,role_name,contest_year,exam_board,source_id)
select 'Polícia Federal','Delegado de Polícia Federal',2025,'CEBRASPE',(select id from public.content_sources where url=$q$https://drive.google.com/file/d/1wspbjh9e8Q2m1I9IpKkbvqCftgrbgW_q/view$q$)
where not exists (
  select 1 from public.syllabus_editions
  where contest_name='Polícia Federal' and role_name='Delegado de Polícia Federal' and contest_year=2025
);

-- Discipline breakdown derived directly from the prova's own command-block
-- headers (not guessed): Direito Administrativo (1-12), Direito
-- Constitucional (13-24, 41-42, 46-49), Direitos Humanos (25-32),
-- Legislação Penal Especial (33-34, 58-59, 93-96), Direito Civil (35-38),
-- Direito Processual Civil (39-40), Direito Empresarial (43-45), Direito
-- Internacional (50-51), Direito Penal (52-57, 60-65, 69-73), Direito
-- Ambiental (66-68, 113-120), Direito Processual Penal (74-92),
-- Criminologia (97-100), Direito Previdenciário (101-106), Direito
-- Financeiro (107-109), Direito Tributário (110-112).
with edition as (
  select id from public.syllabus_editions
  where contest_name='Polícia Federal' and role_name='Delegado de Polícia Federal' and contest_year=2025
)
insert into public.syllabus_topics (edition_id,block_name,discipline,topic_order,topic_text,content_status)
select edition.id,'Prova objetiva',d.discipline,1,d.topic_text,'current'
from edition cross join (values
  ('Direito Administrativo','Licitações, contratos e convênios; Lei de Improbidade Administrativa (Lei nº 8.429/1992); atos administrativos.'),
  ('Direito Constitucional','Jurisprudência do STF em controle de constitucionalidade concentrado, Poder Executivo, Poder Legislativo e processo legislativo, ordem social, direitos dos povos indígenas, sentidos sociológico, político e jurídico da Constituição, ação popular e mandado de segurança individual, asilo político, extradição e expulsão.'),
  ('Direitos Humanos','Convenção Relativa ao Estatuto dos Refugiados; Convenção sobre a Eliminação de Todas as Formas de Discriminação Racial; Convenção sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher; Convenção para a Prevenção e Punição do Crime de Genocídio; Convenção contra a Tortura; Convenção Internacional para a Proteção de Todas as Pessoas contra o Desaparecimento Forçado.'),
  ('Legislação Penal Especial','Princípios básicos sobre o uso da força e armas de fogo e Lei nº 13.060/2014; Lei nº 7.716/1989 (crimes resultantes de preconceito de raça ou de cor); Lei nº 9.613/1998 (lavagem de dinheiro).'),
  ('Direito Civil','Posse, propriedade, responsabilidade civil e prescrição, conforme o entendimento do STJ.'),
  ('Direito Processual Civil','Homologação de sentença estrangeira e continência, conforme o entendimento do STJ.'),
  ('Direito Empresarial','Conceito, classificação e liquidação de sociedades; recuperação judicial e falência.'),
  ('Direito Internacional','Instrumentos de cooperação internacional: Convenção de Palermo e Protocolo de Assistência Jurídica Mútua em Assuntos Penais (Protocolo de São Luís).'),
  ('Direito Penal','Teoria do bem jurídico, extraterritorialidade e imunidade diplomática, crimes contra a honra, crimes contra a fé pública e contra a administração pública, crimes contra a pessoa.'),
  ('Direito Ambiental','Crimes ambientais (Lei nº 9.605/1998), exploração de recursos minerais (Lei nº 8.176/1991), licenciamento ambiental e área de preservação permanente, proteção jurídica do conhecimento tradicional associado e biossegurança, princípio da responsabilidade ambiental intergeracional.'),
  ('Direito Processual Penal','Inquérito policial, competência da justiça federal e dos tribunais superiores, conflito de competência, provas no processo penal, interrogatório do acusado.'),
  ('Criminologia','Teorias sociológicas da criminologia (broken windows theory, crime do colarinho branco) e modelos teóricos (ressocializador e restaurador/justiça restaurativa).'),
  ('Direito Previdenciário','Regime Geral de Previdência Social (RGPS), receitas da seguridade social, crimes contra a seguridade e a previdência social e extinção da punibilidade.'),
  ('Direito Financeiro','Dívida pública, classificação da despesa pública, princípio da unidade orçamentária.'),
  ('Direito Tributário','COFINS, delegação da capacidade tributária ativa e domicílio tributário no Sistema Tributário Nacional.')
) d(discipline,topic_text)
on conflict (edition_id,discipline,topic_order) do update set topic_text=excluded.topic_text;

with imported(exam_year,item_number,subject,question_text,raw_extraction,official_answer,source_page,content_status,legal_review_required,context_review_required,review_note) as (values
(2025,1,$q$Direito Administrativo$q$,$q$Nas licitações, a administração pública deve anular, de ofício ou mediante provocação de terceiros, os próprios atos que contenham vício de legalidade, podendo revogar o procedimento licitatório por motivo de conveniência ou oportunidade, respeitados os direitos adquiridos.$q$,$q$Nas licitações, a administração pública deve anular, de ofício ou mediante provocação de terceiros, os próprios atos que contenham vício de legalidade, podendo revogar o procedimento licitatório por motivo de conveniência ou oportunidade, respeitados os direitos adquiridos.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,2,$q$Direito Administrativo$q$,$q$A administração pública federal pode celebrar convênios e contratos de repasse com entidades privadas com fins lucrativos.$q$,$q$A administração pública federal pode celebrar convênios e contratos de repasse com entidades privadas com fins lucrativos.$q$,'X',1,'annulled',true,false,$q$Item anulado no gabarito oficial definitivo (106_PF_25_GabaritosDefinitivos); não é exibido aos estudantes.$q$),
(2025,3,$q$Direito Administrativo$q$,$q$É vedada a celebração de convênios e contratos de repasse entre órgãos e entidades da administração pública federal.$q$,$q$É vedada a celebração de convênios e contratos de repasse entre órgãos e entidades da administração pública federal.$q$,'X',1,'annulled',true,false,$q$Item anulado no gabarito oficial definitivo (106_PF_25_GabaritosDefinitivos); não é exibido aos estudantes.$q$),
(2025,4,$q$Direito Administrativo$q$,$q$Constitui ato de improbidade administrativa que atenta contra os princípios da administração pública a dispensa indevida de processo licitatório com consequente perda patrimonial efetiva.$q$,$q$Constitui ato de improbidade administrativa que atenta contra os princípios da administração pública a dispensa indevida de processo licitatório com consequente perda patrimonial efetiva.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,5,$q$Direito Administrativo$q$,$q$Consideram-se atos de improbidade administrativa as condutas dos agentes públicos eivadas de erros grosseiros.$q$,$q$Consideram-se atos de improbidade administrativa as condutas dos agentes públicos eivadas de erros grosseiros.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,6,$q$Direito Administrativo$q$,$q$A conduta de frustrar, em ofensa à imparcialidade, o caráter concorrencial de procedimento licitatório, com vistas à obtenção de benefício de terceiros, constitui ato de improbidade administrativa que atenta contra os princípios da administração pública.$q$,$q$A conduta de frustrar, em ofensa à imparcialidade, o caráter concorrencial de procedimento licitatório, com vistas à obtenção de benefício de terceiros, constitui ato de improbidade administrativa que atenta contra os princípios da administração pública.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,7,$q$Direito Administrativo$q$,$q$A prática de ato de improbidade administrativa, por ação ou omissão, requer a demonstração de culpa ou dolo por parte do agente público.$q$,$q$A prática de ato de improbidade administrativa, por ação ou omissão, requer a demonstração de culpa ou dolo por parte do agente público.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,8,$q$Direito Administrativo$q$,$q$Aquele que, não sendo agente público, concorrer dolosamente para a prática de ato de improbidade não estará sujeito às disposições da Lei de Improbidade Administrativa e deverá responder por seus atos de acordo com a legislação penal comum.$q$,$q$Aquele que, não sendo agente público, concorrer dolosamente para a prática de ato de improbidade não estará sujeito às disposições da Lei de Improbidade Administrativa e deverá responder por seus atos de acordo com a legislação penal comum.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,9,$q$Direito Administrativo$q$,$q$Em decorrência dos atributos da presunção de legitimidade e da imperatividade, o ato administrativo cria obrigações aos administrados desde a sua expedição, produzindo normalmente os seus efeitos, até que — se for o caso — seja anulado pela própria administração pública, de oficio ou por provocação, ou pelo Poder Judiciário.$q$,$q$Em decorrência dos atributos da presunção de legitimidade e da imperatividade, o ato administrativo cria obrigações aos administrados desde a sua expedição, produzindo normalmente os seus efeitos, até que — se for o caso — seja anulado pela própria administração pública, de oficio ou por provocação, ou pelo Poder Judiciário.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,10,$q$Direito Administrativo$q$,$q$O ato administrativo composto resulta da necessidade, para sua formação, da manifestação de vontade de dois ou mais diferentes órgãos ou autoridades.$q$,$q$O ato administrativo composto resulta da necessidade, para sua formação, da manifestação de vontade de dois ou mais diferentes órgãos ou autoridades.$q$,'X',1,'annulled',true,false,$q$Item anulado no gabarito oficial definitivo (106_PF_25_GabaritosDefinitivos); não é exibido aos estudantes.$q$),
(2025,11,$q$Direito Administrativo$q$,$q$Atos administrativos de gestão são aqueles praticados pela administração pública na qualidade de gestora de seus bens e serviços, sem exercício de supremacia sobre os particulares.$q$,$q$Atos administrativos de gestão são aqueles praticados pela administração pública na qualidade de gestora de seus bens e serviços, sem exercício de supremacia sobre os particulares.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,12,$q$Direito Administrativo$q$,$q$A prática de ato administrativo em desacordo com o que a lei estabeleça para qualquer de seus requisitos de validade torna-o nulo de pleno direito.$q$,$q$A prática de ato administrativo em desacordo com o que a lei estabeleça para qualquer de seus requisitos de validade torna-o nulo de pleno direito.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,13,$q$Direito Constitucional$q$,$q$Na ADI por omissão, pode o STF, excepcionalmente, em caso de urgência e relevância da matéria, conceder medida cautelar sem a prévia audiência dos órgãos ou das autoridades responsáveis pela omissão inconstitucional.$q$,$q$Na ADI por omissão, pode o STF, excepcionalmente, em caso de urgência e relevância da matéria, conceder medida cautelar sem a prévia audiência dos órgãos ou das autoridades responsáveis pela omissão inconstitucional.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,14,$q$Direito Constitucional$q$,$q$Em sede de ADI, a medida cautelar será concedida por decisão da maioria absoluta dos membros do STF.$q$,$q$Em sede de ADI, a medida cautelar será concedida por decisão da maioria absoluta dos membros do STF.$q$,'X',1,'annulled',true,false,$q$Item anulado no gabarito oficial definitivo (106_PF_25_GabaritosDefinitivos); não é exibido aos estudantes.$q$),
(2025,15,$q$Direito Constitucional$q$,$q$O STF reconheceu a mora do Congresso Nacional na regulamentação do dispositivo que prevê a excepcional participação dos trabalhadores urbanos e rurais na gestão da empresa, tendo fixado o prazo de 24 meses, a contar da publicação da ata do julgamento, para a adoção das medidas legislativas pertinentes à omissão.$q$,$q$O STF reconheceu a mora do Congresso Nacional na regulamentação do dispositivo que prevê a excepcional participação dos trabalhadores urbanos e rurais na gestão da empresa, tendo fixado o prazo de 24 meses, a contar da publicação da ata do julgamento, para a adoção das medidas legislativas pertinentes à omissão.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,16,$q$Direito Constitucional$q$,$q$Considere que uma empresa jornalística tenha publicado entrevista na qual o entrevistado tenha imputado falsamente a prática de crime a terceiro, mesmo havendo, à época da divulgação da informação, indícios concretos da falsidade da imputação, de modo que não fora observado o dever de cuidado da veracidade dos fatos. Nessa situação, em razão da proteção constitucional à liberdade de imprensa, a empresa jornalística que publicou a entrevista não será responsabilizada.$q$,$q$Considere que uma empresa jornalística tenha publicado entrevista na qual o entrevistado tenha imputado falsamente a prática de crime a terceiro, mesmo havendo, à época da divulgação da informação, indícios concretos da falsidade da imputação, de modo que não fora observado o dever de cuidado da veracidade dos fatos. Nessa situação, em razão da proteção constitucional à liberdade de imprensa, a empresa jornalística que publicou a entrevista não será responsabilizada.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,17,$q$Direito Constitucional$q$,$q$É inconstitucional lei de iniciativa parlamentar que cria conselho de representantes da sociedade civil, integrante da estrutura do Poder Legislativo, com atribuição de acompanhar ações do Poder Executivo.$q$,$q$É inconstitucional lei de iniciativa parlamentar que cria conselho de representantes da sociedade civil, integrante da estrutura do Poder Legislativo, com atribuição de acompanhar ações do Poder Executivo.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,18,$q$Direito Constitucional$q$,$q$É possível a edição de medida provisória que trate de matérias relacionadas a cidadania e a direito civil, tributário, urbanístico e financeiro.$q$,$q$É possível a edição de medida provisória que trate de matérias relacionadas a cidadania e a direito civil, tributário, urbanístico e financeiro.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,19,$q$Direito Constitucional$q$,$q$Não tem direito a imunidade parlamentar o deputado ou senador que assumir o cargo de ministro de Estado, estando ele, nesse caso, sujeito à responsabilização pelos atos que praticar.$q$,$q$Não tem direito a imunidade parlamentar o deputado ou senador que assumir o cargo de ministro de Estado, estando ele, nesse caso, sujeito à responsabilização pelos atos que praticar.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,20,$q$Direito Constitucional$q$,$q$É competência privativa do Senado Federal aprovar previamente a escolha dos chefes de missão diplomática de caráter permanente.$q$,$q$É competência privativa do Senado Federal aprovar previamente a escolha dos chefes de missão diplomática de caráter permanente.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,21,$q$Direito Constitucional$q$,$q$A ordem social tem como fundamentos o trabalho e a justiça social e, como objetivos, o bem-estar e a distribuição de renda.$q$,$q$A ordem social tem como fundamentos o trabalho e a justiça social e, como objetivos, o bem-estar e a distribuição de renda.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,22,$q$Direito Constitucional$q$,$q$A tradicionalidade da ocupação indígena abrange as áreas habitadas por indígenas em caráter permanente, as utilizadas para suas atividades produtivas, as imprescindíveis à preservação dos recursos ambientais necessários a seu bem-estar e as necessárias à sua reprodução física e cultural sempre segundo os usos, costumes e tradição da comunidade.$q$,$q$A tradicionalidade da ocupação indígena abrange as áreas habitadas por indígenas em caráter permanente, as utilizadas para suas atividades produtivas, as imprescindíveis à preservação dos recursos ambientais necessários a seu bem-estar e as necessárias à sua reprodução física e cultural sempre segundo os usos, costumes e tradição da comunidade.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,23,$q$Direito Constitucional$q$,$q$Segundo a concepção política, a Constituição é um complexo normativo estabelecido de uma só vez, em que, de maneira total, exaustiva e sistemática, são estabelecidas as funções fundamentais do Estado e regulados os órgãos, o âmbito de suas competências e as relações entre eles.$q$,$q$Segundo a concepção política, a Constituição é um complexo normativo estabelecido de uma só vez, em que, de maneira total, exaustiva e sistemática, são estabelecidas as funções fundamentais do Estado e regulados os órgãos, o âmbito de suas competências e as relações entre eles.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,24,$q$Direito Constitucional$q$,$q$O sociologismo constitucional fundamenta-se em afirmações como, por exemplo, a de que a Constituição é imanência das situações e estruturas sociais do presente e a de que a Constituição não se sustenta em uma norma transcendente.$q$,$q$O sociologismo constitucional fundamenta-se em afirmações como, por exemplo, a de que a Constituição é imanência das situações e estruturas sociais do presente e a de que a Constituição não se sustenta em uma norma transcendente.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,25,$q$Direitos Humanos$q$,$q$Os Estados-partes da Convenção sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher devem conceder às mulheres prioridades no que diz respeito a direitos e responsabilidades referentes a tutela, curatela, guarda e adoção dos filhos, ou institutos análogos.$q$,$q$Os Estados-partes da Convenção sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher devem conceder às mulheres prioridades no que diz respeito a direitos e responsabilidades referentes a tutela, curatela, guarda e adoção dos filhos, ou institutos análogos.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,26,$q$Direitos Humanos$q$,$q$De acordo com a Convenção Relativa ao Estatuto dos Refugiados, os Estados contratantes não devem impor aos refugiados despesas fiscais, a exemplo de taxas e impostos.$q$,$q$De acordo com a Convenção Relativa ao Estatuto dos Refugiados, os Estados contratantes não devem impor aos refugiados despesas fiscais, a exemplo de taxas e impostos.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,27,$q$Direitos Humanos$q$,$q$A adesão à Convenção Relativa ao Estatuto dos Refugiados impõe ao Estado contratante a obrigação de conceder aos refugiados o mesmo tratamento concedido aos nacionais no que se refere ao ensino primário.$q$,$q$A adesão à Convenção Relativa ao Estatuto dos Refugiados impõe ao Estado contratante a obrigação de conceder aos refugiados o mesmo tratamento concedido aos nacionais no que se refere ao ensino primário.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,28,$q$Direitos Humanos$q$,$q$Os Estados-partes da Convenção sobre a Eliminação de Todas as Formas de Discriminação Racial devem assegurar a qualquer pessoa que estiver sob sua jurisdição o direito de pleitear, perante os tribunais nacionais, reparação justa e adequada por qualquer dano de que tenha sido vítima em decorrência de tal discriminação.$q$,$q$Os Estados-partes da Convenção sobre a Eliminação de Todas as Formas de Discriminação Racial devem assegurar a qualquer pessoa que estiver sob sua jurisdição o direito de pleitear, perante os tribunais nacionais, reparação justa e adequada por qualquer dano de que tenha sido vítima em decorrência de tal discriminação.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,29,$q$Direitos Humanos$q$,$q$De acordo com o STF, a expressão "grave violação dos direitos humanos" remete especificamente ao rol taxativo e restritivo de atentados de grande monta aos direitos humanos previstos nos instrumentos normativos internacionais de proteção a cuja aplicabilidade o Brasil formalmente aderiu.$q$,$q$De acordo com o STF, a expressão "grave violação dos direitos humanos" remete especificamente ao rol taxativo e restritivo de atentados de grande monta aos direitos humanos previstos nos instrumentos normativos internacionais de proteção a cuja aplicabilidade o Brasil formalmente aderiu.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,30,$q$Direitos Humanos$q$,$q$Pelo atributo da inerência dos direitos humanos, esses direitos são extensíveis a todos os indivíduos, sem qualquer distinção, enquanto, pelo atributo da transnacionalidade, reconhecem-se os direitos humanos onde quer que o indivíduo esteja.$q$,$q$Pelo atributo da inerência dos direitos humanos, esses direitos são extensíveis a todos os indivíduos, sem qualquer distinção, enquanto, pelo atributo da transnacionalidade, reconhecem-se os direitos humanos onde quer que o indivíduo esteja.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,31,$q$Direitos Humanos$q$,$q$Os Estados-partes das citadas convenções referentes a tortura e desaparecimento forçado são impedidos de promover a expulsão, devolução ou extradição de pessoa a Estado onde haja risco de ela ser vítima de desaparecimento forçado ou submetida a tortura.$q$,$q$Os Estados-partes das citadas convenções referentes a tortura e desaparecimento forçado são impedidos de promover a expulsão, devolução ou extradição de pessoa a Estado onde haja risco de ela ser vítima de desaparecimento forçado ou submetida a tortura.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,32,$q$Direitos Humanos$q$,$q$O genocídio não pode ser considerado crime político para efeitos de extradição.$q$,$q$O genocídio não pode ser considerado crime político para efeitos de extradição.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,33,$q$Legislação Penal Especial$q$,$q$A conduta dos policiais de não atirar no momento em que o caminhão acelerou para o lado oposto do bloqueio policial foi adequada, considerada a inexistência de risco de morte ou lesão aos policiais naquele momento.$q$,$q$A conduta dos policiais de não atirar no momento em que o caminhão acelerou para o lado oposto do bloqueio policial foi adequada, considerada a inexistência de risco de morte ou lesão aos policiais naquele momento.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,34,$q$Legislação Penal Especial$q$,$q$A conduta dos policiais de se identificarem perante o motorista do caminhão antes de atirar foi equivocada, uma vez que, ante a probabilidade de reação, o recomendado é agir de imediato, no intuito de interromper a ação delituosa.$q$,$q$A conduta dos policiais de se identificarem perante o motorista do caminhão antes de atirar foi equivocada, uma vez que, ante a probabilidade de reação, o recomendado é agir de imediato, no intuito de interromper a ação delituosa.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
