(2025,107,$q$Direito Financeiro$q$,$q$A dívida pública corresponde aos créditos inscritos em dívida ativa da União, oriundos de tributos não pagos e de outras obrigações inadimplidas.$q$,$q$A dívida pública corresponde aos créditos inscritos em dívida ativa da União, oriundos de tributos não pagos e de outras obrigações inadimplidas.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,108,$q$Direito Financeiro$q$,$q$A despesa pública pode ser classificada, quanto à sua natureza, em despesas correntes e em despesas de capital, estando os juros da dívida pública incluídos nas despesas de capital.$q$,$q$A despesa pública pode ser classificada, quanto à sua natureza, em despesas correntes e em despesas de capital, estando os juros da dívida pública incluídos nas despesas de capital.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,109,$q$Direito Financeiro$q$,$q$Embora a Constituição Federal de 1988 preveja diversos tipos de leis orçamentárias, ela consagra o princípio da unidade orçamentária, razão por que cada ente federativo deve ter apenas um único orçamento anual para cada exercício financeiro.$q$,$q$Embora a Constituição Federal de 1988 preveja diversos tipos de leis orçamentárias, ela consagra o princípio da unidade orçamentária, razão por que cada ente federativo deve ter apenas um único orçamento anual para cada exercício financeiro.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,110,$q$Direito Tributário$q$,$q$A contribuição para o financiamento da seguridade social (COFINS) admite os regimes de apuração cumulativo e não cumulativo, sendo, neste último, permitida a dedução de créditos apurados com base em custos, despesas e encargos da pessoa jurídica contribuinte.$q$,$q$A contribuição para o financiamento da seguridade social (COFINS) admite os regimes de apuração cumulativo e não cumulativo, sendo, neste último, permitida a dedução de créditos apurados com base em custos, despesas e encargos da pessoa jurídica contribuinte.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,111,$q$Direito Tributário$q$,$q$A administração tributária pode delegar a função de arrecadação de tributos a instituições financeiras sem que isso implique a delegação da competência tributária.$q$,$q$A administração tributária pode delegar a função de arrecadação de tributos a instituições financeiras sem que isso implique a delegação da competência tributária.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,112,$q$Direito Tributário$q$,$q$Considera-se como domicílio tributário da pessoa natural o local da sua residência habitual, sendo vedada a indicação de outro domicílio pelo contribuinte.$q$,$q$Considera-se como domicílio tributário da pessoa natural o local da sua residência habitual, sendo vedada a indicação de outro domicílio pelo contribuinte.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,113,$q$Direito Ambiental$q$,$q$De acordo com a jurisprudência do STJ, seria cabível a aplicação da teoria do fato consumado ao caso apenas se a construção já estivesse consolidada.$q$,$q$De acordo com a jurisprudência do STJ, seria cabível a aplicação da teoria do fato consumado ao caso apenas se a construção já estivesse consolidada.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,114,$q$Direito Ambiental$q$,$q$Na situação apresentada, foi indevida a concessão da licença ambiental, pois a vegetação nativa de restinga é sempre considerada área de preservação permanente.$q$,$q$Na situação apresentada, foi indevida a concessão da licença ambiental, pois a vegetação nativa de restinga é sempre considerada área de preservação permanente.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,115,$q$Direito Ambiental$q$,$q$Eventual condenação da construtora a recuperar a área lesionada não a isentará do dever de indenizar pelo dano que permanecer até o pleno restabelecimento do meio ambiente afetado, pelo dano moral coletivo e pelo dano residual, segundo entendimento do STJ.$q$,$q$Eventual condenação da construtora a recuperar a área lesionada não a isentará do dever de indenizar pelo dano que permanecer até o pleno restabelecimento do meio ambiente afetado, pelo dano moral coletivo e pelo dano residual, segundo entendimento do STJ.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,116,$q$Direito Ambiental$q$,$q$Em situações devidamente justificadas, é permitida a comercialização de células-tronco embrionárias obtidas de embriões humanos produzidos por fertilização in vitro e não utilizados no respectivo procedimento, desde que haja autorização dos genitores.$q$,$q$Em situações devidamente justificadas, é permitida a comercialização de células-tronco embrionárias obtidas de embriões humanos produzidos por fertilização in vitro e não utilizados no respectivo procedimento, desde que haja autorização dos genitores.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,117,$q$Direito Ambiental$q$,$q$IBAMA, ICMBio, Marinha do Brasil e Ministério da Agricultura, Pecuária e Abastecimento têm competência para a apuração e fiscalização das infrações administrativas contra o patrimônio genético nacional ou o conhecimento tradicional associado, conforme o tipo de infração e o local de sua ocorrência.$q$,$q$IBAMA, ICMBio, Marinha do Brasil e Ministério da Agricultura, Pecuária e Abastecimento têm competência para a apuração e fiscalização das infrações administrativas contra o patrimônio genético nacional ou o conhecimento tradicional associado, conforme o tipo de infração e o local de sua ocorrência.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,118,$q$Direito Ambiental$q$,$q$A CF consagra o princípio da responsabilidade ambiental entre as gerações, impondo às gerações presentes o dever de defender e preservar o meio ambiente ecologicamente equilibrado para si e para as gerações vindouras.$q$,$q$A CF consagra o princípio da responsabilidade ambiental entre as gerações, impondo às gerações presentes o dever de defender e preservar o meio ambiente ecologicamente equilibrado para si e para as gerações vindouras.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,119,$q$Direito Ambiental$q$,$q$A Lei de Crimes Ambientais determina que os instrumentos utilizados na prática de infração ambiental sejam doados a instituições científicas e educacionais.$q$,$q$A Lei de Crimes Ambientais determina que os instrumentos utilizados na prática de infração ambiental sejam doados a instituições científicas e educacionais.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,120,$q$Direito Ambiental$q$,$q$Considerando-se a jurisprudência do STJ, é correto afirmar que, independentemente de o uso dos instrumentos apreendidos com José ser específico, exclusivo ou habitual, é permitida sua apreensão, uma vez que ele praticou infração ambiental.$q$,$q$Considerando-se a jurisprudência do STJ, é correto afirmar que, independentemente de o uso dos instrumentos apreendidos com José ser específico, exclusivo ou habitual, é permitida sua apreensão, uma vez que ele praticou infração ambiental.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas 106_PF_001_01 (Cargo 1: Delegado de Polícia Federal, PF 2025); gabarito conferido em 106_PF_25_GabaritosDefinitivos. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$)
), editions as (
  select id,contest_year from public.syllabus_editions
  where contest_name='Polícia Federal' and role_name='Delegado de Polícia Federal' and contest_year=2025
), resolved as (
  select imported.*, question_source.id question_source_id, answer_source.id answer_key_source_id, topic.id syllabus_topic_id
  from imported
  join editions on editions.contest_year=imported.exam_year
  join public.syllabus_topics topic on topic.edition_id=editions.id and topic.discipline=imported.subject and topic.topic_order=1
  join public.content_sources question_source on question_source.title='Prova objetiva PF - Delegado - ' || imported.exam_year
  join public.content_sources answer_source on answer_source.title='Gabarito definitivo PF - Delegado - ' || imported.exam_year
)
insert into public.official_exam_questions (
  question_source_id,answer_key_source_id,syllabus_topic_id,contest_name,career_name,exam_board,exam_year,item_number,subject,
  question_text,raw_extraction,official_answer,source_page,content_status,legal_review_required,
  context_review_required,review_note
)
select question_source_id,answer_key_source_id,syllabus_topic_id,'Polícia Federal','Delegado de Polícia Federal','CEBRASPE',exam_year,item_number,subject,
  question_text,raw_extraction,official_answer,source_page,content_status,legal_review_required,
  context_review_required,review_note
from resolved
on conflict (contest_name,career_name,exam_year,item_number) do nothing;
